WITH flattened AS (SELECT id, service, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, v), unpacked AS (SELECT id, service, latency_ms, status_code, key, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS has_fault FROM flattened), metrics AS (SELECT *, LEAD(latency_ms, 1, 0) OVER (PARTITION BY key ORDER BY has_fault, id, key) AS next_latency_ms, ROUND(status_code / SUM(status_code) OVER (PARTITION BY service), 4) AS status_code_share FROM unpacked WHERE key IN ('trace', 'version', 'region')), remaining_keys AS (SELECT id, service FROM metrics EXCEPT SELECT id, service FROM app_logs WHERE level IN ('DEBUG', 'INFO', 'WARN')), kept_rows AS (SELECT s.* FROM metrics s JOIN remaining_keys k ON s.id = k.id AND s.service = k.service), metrics_app_logs AS (SELECT *, DENSE_RANK() OVER (PARTITION BY key ORDER BY status_code_share DESC) AS status_code_share_dense_rank, PERCENT_RANK() OVER (PARTITION BY key ORDER BY status_code_share DESC NULLS LAST) AS status_code_share_percent_rank, DENSE_RANK() OVER (PARTITION BY service ORDER BY next_latency_ms DESC NULLS LAST) AS next_latency_ms_dense_rank, CUME_DIST() OVER (ORDER BY has_fault DESC NULLS FIRST) AS has_fault_cume_dist FROM kept_rows) SELECT CASE WHEN status_code_share_percent_rank >= 0.85 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_share_percent_rank_tier, key, COUNT(*) FILTER (WHERE service = 'checkout') AS checkout_rows, COUNT_IF(key = 'trace') AS trace_events, COUNT(*) AS event_count, RANK() OVER (PARTITION BY CASE WHEN status_code_share_percent_rank >= 0.85 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT_IF(key = 'trace') DESC) AS trace_events_rank FROM metrics_app_logs GROUP BY CASE WHEN status_code_share_percent_rank >= 0.85 THEN 'PREMIUM' ELSE 'STANDARD' END, key ORDER BY key DESC NULLS FIRST;
